// SPDX-License-Identifier: MIT
// Shuntline (Prismheart campaign), plain C++17 for the Unreal binding. A port of tools/minigames/shuntline.py
// (unreal-team), which stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h,
// "shuntline:<seed>:<difficulty>") and the only draws are randrange at setup (repeated until the exact search sorts
// the train within the budget); nothing is random after. Byte parity goes through
// engines/unreal/core-test/shuntline_parity.txt (shuntline_core_test.cpp), generated by
// tools/minigames/shuntline_parity.py.
//
// Rules: carriages tagged 1..Destinations arrive in order. Each move sends the front carriage out, shunts it onto a
// siding (a stack of at most Length), or pulls a siding's top carriage out. The outbound order may never go down.
// Every carriage out within Moves wins (+GroupScore per destination present, +MoveBonus per move left); the moves
// running out, or no legal move, loses. The yardmaster (demo) is an exact search with memo, dead-carriage prunes and
// a node budget; the state is small enough that the whole yard fits in fixed arrays.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <array>
#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

namespace daedalus { namespace shuntline {

inline const char* GameId() { return "shuntline"; }
inline const char* Title() { return "Shuntline"; }

constexpr int GroupScore = 10, MoveBonus = 2;
constexpr int SearchNodes = 20000, MaxRedraws = 50;
constexpr int MaxCars = 16, MaxSidings = 4, MaxLength = 4;

struct Difficulty { const char* Name; int Cars; int Destinations; int Sidings; int Length; int Moves; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 7, 3, 2, 3, 16 }, { "normal", 9, 4, 2, 3, 20 }, { "hard", 11, 5, 3, 3, 24 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

/** An action: Out, Shunt onto siding N, or Pull from siding N. */
enum class Kind : int { Out = 0, Shunt, Pull };
struct Action { Kind K = Kind::Out; int Siding = 0; bool operator==(const Action& O) const noexcept { return K == O.K && (K == Kind::Out || Siding == O.Siding); } };
constexpr Action OutAction{ Kind::Out, 0 };

/** A siding: a stack of tags, bottom first. */
struct Siding { std::array<int, MaxLength> Tag{}; int N = 0; int Top() const noexcept { return Tag[static_cast<size_t>(N - 1)]; } };

/** The yard as the search sees it: the inbound index, the sidings, the last tag out, and the moves left. */
struct Yard
{
	int Index = 0, OutLast = 0, Moves = 0;
	std::array<Siding, MaxSidings> Sidings{};
	std::string Key(int SidingCount) const
	{
		std::string K; K.reserve(24);
		K.push_back(static_cast<char>(Index)); K.push_back(static_cast<char>(OutLast)); K.push_back(static_cast<char>(Moves));
		for (int S = 0; S < SidingCount; ++S) { K.push_back(static_cast<char>(Sidings[static_cast<size_t>(S)].N + 16)); for (int I = 0; I < Sidings[static_cast<size_t>(S)].N; ++I) K.push_back(static_cast<char>(Sidings[static_cast<size_t>(S)].Tag[static_cast<size_t>(I)])); }
		return K;
	}
};

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<int> Train, Outbound;
	Yard State;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, Illegal, GameOver };

	int Cars() const noexcept { return static_cast<int>(Train.size()); }
	int Index() const noexcept { return State.Index; }
	int Moves() const noexcept { return State.Moves; }
	int OutLast() const noexcept { return State.OutLast; }
	const Siding& SidingAt(int S) const noexcept { return State.Sidings[static_cast<size_t>(S)]; }
	int Front() const noexcept { return State.Index < Cars() ? Train[static_cast<size_t>(State.Index)] : 0; }
	int Remaining() const noexcept { int R = Cars() - State.Index; for (int S = 0; S < Diff->Sidings; ++S) R += SidingAt(S).N; return R; }
	/** Game.fresh: no move yet, so the screen shows its tutorial rows. */
	bool FreshYard() const noexcept { return State.Index == 0 && !Over; }

	/** candidate_actions: out, shunt onto each siding, pull from each siding — in the rules' order. */
	static int Candidates(const std::vector<int>& Train, const Yard& Y, const Difficulty& D, std::array<Action, 1 + 2 * MaxSidings>& Out) noexcept
	{
		int N = 0;
		const int Cars = static_cast<int>(Train.size());
		if (Y.Index < Cars)
		{
			if (Train[static_cast<size_t>(Y.Index)] >= Y.OutLast) Out[static_cast<size_t>(N++)] = OutAction;
			for (int S = 0; S < D.Sidings; ++S) if (Y.Sidings[static_cast<size_t>(S)].N < D.Length) Out[static_cast<size_t>(N++)] = { Kind::Shunt, S };
		}
		for (int S = 0; S < D.Sidings; ++S)
		{
			const Siding& Sd = Y.Sidings[static_cast<size_t>(S)];
			if (Sd.N > 0 && Sd.Top() >= Y.OutLast) Out[static_cast<size_t>(N++)] = { Kind::Pull, S };
		}
		return N;
	}
	int Actions(std::array<Action, 1 + 2 * MaxSidings>& Out) const noexcept { return Diff ? Candidates(Train, State, *Diff, Out) : 0; }
	bool IsLegal(const Action& A) const noexcept
	{
		std::array<Action, 1 + 2 * MaxSidings> Acts{};
		const int N = Actions(Acts);
		for (int I = 0; I < N; ++I) if (Acts[static_cast<size_t>(I)] == A) return true;
		return false;
	}

	/** apply: the yard after `A`; returns the tag that left (0 when none). */
	static int Apply(const std::vector<int>& Train, Yard& Y, const Action& A) noexcept
	{
		if (A.K == Kind::Out) { const int Car = Train[static_cast<size_t>(Y.Index)]; ++Y.Index; Y.OutLast = Car; --Y.Moves; return Car; }
		Siding& S = Y.Sidings[static_cast<size_t>(A.Siding)];
		if (A.K == Kind::Shunt) { S.Tag[static_cast<size_t>(S.N++)] = Train[static_cast<size_t>(Y.Index)]; ++Y.Index; --Y.Moves; return 0; }
		const int Car = S.Top(); --S.N; Y.OutLast = Car; --Y.Moves; return Car;
	}

	/** PrismGame.start + Game.setup: draw trains until the search sorts one within the budget. False on an unknown difficulty. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Cars > MaxCars || Diff->Sidings > MaxSidings || Diff->Length > MaxLength) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		for (int Attempt = 0; Attempt < MaxRedraws; ++Attempt)
		{
			Train.assign(static_cast<size_t>(Diff->Cars), 0);
			for (int& T : Train) T = 1 + static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(Diff->Destinations)));
			State = Yard{}; State.Moves = Diff->Moves; Outbound.clear();
			Action First;
			if (Search(First)) break;
		}
		return true;
	}

	/** Game.act. `Result` mirrors the Python result text. */
	Act Step(const Action& A, std::string& Result)
	{
		if (Over) return Act::GameOver;
		if (!IsLegal(A)) return Act::Illegal;
		const int Car = A.K == Kind::Shunt ? Front() : 0;
		const int Left = Apply(Train, State, A);
		if (Left) Outbound.push_back(Left);
		if (A.K == Kind::Out) Result = "out: carriage " + std::to_string(Left) + " leaves";
		else if (A.K == Kind::Shunt) Result = "s" + std::to_string(A.Siding) + ": carriage " + std::to_string(Car) + " onto siding " + std::to_string(A.Siding);
		else Result = "p" + std::to_string(A.Siding) + ": carriage " + std::to_string(Left) + " pulled out";
		if (Remaining() == 0) { Score = GroupScore * Groups() + MoveBonus * State.Moves; Over = Won = true; Result += "; the train is made up"; return Act::Ok; }
		if (State.Moves <= 0) { Score = GroupScore * Groups(); Over = true; Won = false; Result += "; the shift ends"; return Act::Ok; }
		std::array<Action, 1 + 2 * MaxSidings> Acts{};
		if (Actions(Acts) == 0) { Score = GroupScore * Groups(); Over = true; Won = false; Result += "; the yard is blocked"; return Act::Ok; }
		return Act::Ok;
	}
	/** len(set(outbound)): destinations represented on the outbound track. */
	int Groups() const noexcept
	{
		bool Seen[16] = {}; int N = 0;
		for (int T : Outbound) if (T >= 0 && T < 16 && !Seen[T]) { Seen[T] = true; ++N; }
		return N;
	}

	/** Game.preview: (legal, carriage moved, leaves the yard). */
	bool Preview(const Action& A, int& Car, bool& Leaves) const noexcept
	{
		Car = 0; Leaves = false;
		if (Over || !IsLegal(A)) return false;
		if (A.K == Kind::Pull) { Car = SidingAt(A.Siding).Top(); Leaves = true; return true; }
		Car = Front(); Leaves = A.K == Kind::Out;
		return true;
	}

	/** Game.demo_action, the yardmaster: the search's first action, else the first legal action. */
	Action DemoAction() const
	{
		Action Found;
		if (Search(Found)) return Found;
		std::array<Action, 1 + 2 * MaxSidings> Acts{};
		return Actions(Acts) > 0 ? Acts[0] : OutAction;
	}

	/** solve: the first winning action from the current yard, false when none (or the budget runs out). */
	bool Search(Action& First) const
	{
		std::unordered_map<std::string, signed char> Memo;   // 1 win, 0 none
		int Nodes = 0;
		const int R = Solve(State, Memo, Nodes, &First);
		return R == 1 && !(Remaining() == 0);
	}
	/** 1 = winning line, 0 = none, -1 = budget. With `First`, the winning action at this node is written back. */
	int Solve(const Yard& Y, std::unordered_map<std::string, signed char>& Memo, int& Nodes, Action* First) const
	{
		const std::string Key = Y.Key(Diff->Sidings);
		const auto Found = Memo.find(Key);
		if (Found != Memo.end() && !First) return Found->second;
		++Nodes;
		if (Nodes > SearchNodes) return -1;
		int Remain = Cars() - Y.Index;
		for (int S = 0; S < Diff->Sidings; ++S) Remain += Y.Sidings[static_cast<size_t>(S)].N;
		if (Remain == 0) { Memo[Key] = 1; return 1; }
		if (Y.Moves <= 0 || Remain > Y.Moves) { Memo[Key] = 0; return 0; }
		for (int I = Y.Index; I < Cars(); ++I) if (Train[static_cast<size_t>(I)] < Y.OutLast) { Memo[Key] = 0; return 0; }
		for (int S = 0; S < Diff->Sidings; ++S)
		{
			const Siding& Sd = Y.Sidings[static_cast<size_t>(S)];
			for (int I = 0; I < Sd.N; ++I) if (Sd.Tag[static_cast<size_t>(I)] < Y.OutLast) { Memo[Key] = 0; return 0; }
			for (int I = 0; I + 1 < Sd.N; ++I) if (Sd.Tag[static_cast<size_t>(I)] < Sd.Tag[static_cast<size_t>(I + 1)]) { Memo[Key] = 0; return 0; }
		}
		std::array<Action, 1 + 2 * MaxSidings> Acts{};
		const int N = Candidates(Train, Y, *Diff, Acts);
		for (int I = 0; I < N; ++I)
		{
			Yard Next = Y;
			Apply(Train, Next, Acts[static_cast<size_t>(I)]);
			const int Sub = Solve(Next, Memo, Nodes, nullptr);
			if (Nodes > SearchNodes) return -1;
			if (Sub == 1) { Memo[Key] = 1; if (First) *First = Acts[static_cast<size_t>(I)]; return 1; }
		}
		Memo[Key] = 0;
		return 0;
	}

	static std::string Ints(const int* V, int N)
	{
		if (N == 0) return "-";
		std::string Out;
		for (int I = 0; I < N; ++I) { if (I) Out.push_back(','); Out += std::to_string(V[I]); }
		return Out;
	}
	std::string TrainString() const { return Ints(Train.data(), Cars()); }
	std::string OutboundString() const { return Ints(Outbound.data(), static_cast<int>(Outbound.size())); }
	std::string SidingsString() const
	{
		std::string Out;
		for (int S = 0; S < Diff->Sidings; ++S) { if (S) Out.push_back(';'); Out += Ints(SidingAt(S).Tag.data(), SidingAt(S).N); }
		return Out;
	}
};

inline std::string ActionText(const Action& A)
{
	if (A.K == Kind::Out) return "out";
	return std::string(A.K == Kind::Shunt ? "s" : "p") + std::to_string(A.Siding);
}
inline bool ActionFromText(const std::string& Text, Action& Out)
{
	if (Text == "out") { Out = OutAction; return true; }
	if (Text.size() < 2 || (Text[0] != 's' && Text[0] != 'p')) return false;
	for (size_t I = 1; I < Text.size(); ++I) if (Text[I] < '0' || Text[I] > '9') return false;
	Out = { Text[0] == 's' ? Kind::Shunt : Kind::Pull, std::stoi(Text.substr(1)) };
	return true;
}

} } // namespace daedalus::shuntline
